using Avalonia.Controls; using Avalonia.Interactivity;
namespace TCMPlus.App.Views;
public partial class MessageWindow : Window { private readonly bool _confirmation; public MessageWindow(string heading,string message,bool confirmation=false,string confirmationText="Delete",string cancelText="Cancel") { InitializeComponent(); _confirmation=confirmation; Heading.Text=heading; Message.Text=message; CancelButton.IsVisible=confirmation; CancelButton.Content=cancelText; ConfirmButton.Content=confirmation?confirmationText:"OK"; } public MessageWindow():this("",""){} private void OnCancel(object? s,RoutedEventArgs e)=>Close(false); private void OnConfirm(object? s,RoutedEventArgs e)=>Close(_confirmation); }
